# bash completion for weird, generated by `weird completions bash`
# install: weird completions bash > ~/.local/share/bash-completion/completions/weird
_weird() {
    local cur prev cmd="" sub="" i words=""
    cur=${COMP_WORDS[COMP_CWORD]}
    prev=${COMP_WORDS[COMP_CWORD-1]}
    case "$prev" in
        --campaigns|--events|--limit|--offline|--pkgbuild-dir|--poll|--proc-root|--prometheus|--skip|--sysroot) compopt -o default 2>/dev/null; COMPREPLY=(); return ;;
    esac
    for ((i = 1; i < COMP_CWORD; i++)); do
        case ${COMP_WORDS[i]} in
            --campaigns|--events|--limit|--offline|--pkgbuild-dir|--poll|--proc-root|--prometheus|--skip|--sysroot) ((i++)) ;;
            -*) ;;
            *) if [ -z "$cmd" ]; then cmd=${COMP_WORDS[i]}; elif [ -z "$sub" ]; then sub=${COMP_WORDS[i]}; fi ;;
        esac
    done
    case "$cmd $sub" in
        "dev rules show") words="-h --help --defaults" ;;
        "dev rules init") words="-h --help --force" ;;
        "dev fixture record") words="-h --help" ;;
        "dev scan") words="-h --help" ;;
        "dev inspect") words="-h --help" ;;
        "dev trust") words="-h --help" ;;
        "dev rules") words="-h --help show init" ;;
        "dev cache") words="-h --help --rebuild" ;;
        "dev watch") words="-h --help --poll --events --follow --no-follow --falco --journal" ;;
        "dev restart-needed") words="-h --help --json" ;;
        "dev persist") words="-h --help --json -a --all --journal --prometheus" ;;
        "dev hidden") words="-h --help --json --deep --journal --prometheus" ;;
        "dev kernel") words="-h --help --json --journal --prometheus" ;;
        "dev aur") words="-h --help --json -a --all --pkgbuild-dir --campaigns --fetch-campaigns --journal --prometheus" ;;
        "dev self-check") words="-h --help --json" ;;
        "dev offline") words="-h --help --force --limit --json --pkgbuild-dir --journal --prometheus" ;;
        "dev fixture") words="-h --help record" ;;
        "dev falco-rules") words="-h --help" ;;
        "dev man") words="-h --help" ;;
        "dev completions") words="-h --help bash fish" ;;
        "dev baseline") words="-h --help init show diff trust untrust" ;;
        "trust "*) words="-h --help" ;;
        "untrust "*) words="-h --help" ;;
        "watch "*) words="-h --help --poll --events --follow --no-follow --falco --journal" ;;
        "dev "*) words="-h --help scan inspect trust rules cache watch restart-needed persist hidden kernel aur self-check offline fixture falco-rules man completions baseline" ;;
        " ") words="-h --help --version -v --verbose --json --ndjson --journal --prometheus --deep --offline --skip --no-prompt --campaigns --fetch-campaigns --save-baseline --no-baseline --proc-root --sysroot trust untrust watch dev" ;;
    esac
    mapfile -t COMPREPLY < <(compgen -W "$words" -- "$cur")
}
complete -F _weird weird
